"""Physical chemistry on the ACS Physical Chemistry Anchoring Concepts Content Map (Nov 2026; map read in full from the
J. Chem. Educ. 2018 supporting information). OBJS are new PC objectives for map articulations no objective answered;
their `std` lists the map items (scripts/accm_pchem.py has the labels). Two types each; numbers recomputed by sympy."""
from opl_dsl import Q

FILE, FRAMEWORK = "pc-accm", "physical-chemistry"
MC = ["{{o1}}", "{{o2}}", "{{o3}}", "{{o4}}"]
M = lambda *c: [f"acs-accm-pchem:{x}" for x in c]
R_ = "Rational(8314, 1000)"


def facts(name, skill, rows, explain, pace="recall"):
    return Q(name, skill, "{{q}}", pace=pace, cases=[{"q": q, "o1": a, "o2": b, "o3": c, "o4": d} for q, a, b, c, d in rows],
             choice=MC, correct="0", verify="authored", explain=explain)


